import { Queue } from "bullmq";
import { Redis } from "ioredis";

const redisUrl = process.env.REDIS_URL || "redis://127.0.0.1:6379";
const connection = new Redis(redisUrl, { maxRetriesPerRequest: null });


export const jobQueue = new Queue("jobs", { connection });

export async function addJobToQueue(payload: Record<string, any>) {
    // jobId is auto-generated by BullMQ; you can pass customId if desired
    const job = await jobQueue.add("processJob", payload, {
        removeOnComplete: true,
        removeOnFail: 100
    });

    return String(job.id);

}